import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) b[i] = nextLong();
        // x / y: longest valid run ending here when position i takes a[i] / b[i].
        int x = 1, y = 1, best = 1;
        for (int i = 1; i < n; i++) {
            int nx = 1, ny = 1;
            if (a[i - 1] <= a[i]) nx = Math.max(nx, x + 1);
            if (b[i - 1] <= a[i]) nx = Math.max(nx, y + 1);
            if (a[i - 1] <= b[i]) ny = Math.max(ny, x + 1);
            if (b[i - 1] <= b[i]) ny = Math.max(ny, y + 1);
            x = nx;
            y = ny;
            best = Math.max(best, Math.max(x, y));
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a, b := make([]int64, n), make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range b {
		b[i] = nextInt()
	}
	// x / y: longest valid run ending here when position i takes a[i] / b[i].
	x, y, best := 1, 1, 1
	for i := 1; i < n; i++ {
		nx, ny := 1, 1
		if a[i-1] <= a[i] {
			nx = max(nx, x+1)
		}
		if b[i-1] <= a[i] {
			nx = max(nx, y+1)
		}
		if a[i-1] <= b[i] {
			ny = max(ny, x+1)
		}
		if b[i-1] <= b[i] {
			ny = max(ny, y+1)
		}
		x, y = nx, ny
		best = max(best, x, y)
	}
	fmt.Println(best)
}
